// CC-BY

// sign function, but 0 retuns -1 instead of 0
vec2 sign2(vec2 x) {
    return -2.0 * step(x, vec2(0.0)) + 1.0;
}

vec2 to_segment(vec2 p, vec2 start, vec2 end) {
	vec2 sp = p - start;
	vec2 se = end - start;
	float dist = clamp(dot(sp, se) / dot(se, se), 0.0, 1.0);
	vec2 to_line = se * dist - sp;
	return to_line;
}

vec4 hex_side(vec2 p) {
    float s = sqrt(3.0);

    // Squish on y-axis
    vec2 sp = p;
    sp.y /= s;

    // Rectangular cell
    vec2 rec_cell = floor(sp);

    // Points of interest
    vec2 center = rec_cell + vec2(0.5);
    vec2 center_to_sp = sp - center;
    vec2 center_to_corner = sign2(center_to_sp) * vec2(0.5);
    vec2 corner = center + center_to_corner;

    // Undo the squish
    center.y *= s;
    corner.y *= s;

    // Compare vectors
    vec2 center_to_p = center - p;
    vec2 corner_to_p = corner - p;
    bool center_is_nearer = dot(center_to_p, center_to_p) < dot(corner_to_p, corner_to_p);

    vec2 hex_center = center_is_nearer ? center : corner;

    // Find the center of the nearest side
    vec2 hex_to_p = p - hex_center;
    vec2 hex_to_p_sign = sign2(hex_to_p);

    // Go to left or right
    vec2 left_right = vec2(hex_to_p_sign.x, 0.0);

    // Optionally go up or down
    vec2 abs_hex_to_p = abs(hex_to_p);
    float should_go = step(sqrt(3.0) / 3.0 * abs_hex_to_p.x, abs_hex_to_p.y);
    vec2 up_down = should_go * 0.5 * vec2(-1.0, 1.0) * hex_to_p_sign * vec2(1.0, sqrt(3.0));

    vec2 side_center = hex_center + 0.5 * (left_right + up_down);

    // Form a segment around the center of the side
    vec2 center_to_side = side_center - hex_center;
    vec2 segment_dir = vec2(center_to_side.y, -center_to_side.x);

    // Vector to the nearest side from p
    vec2 p_to_side = to_segment(p, side_center + segment_dir, side_center - segment_dir);

    return vec4(hex_center, p_to_side);
}

// https://www.shadertoy.com/view/4djSRW
// For color
vec3 hash32(vec2 p) {
	vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy+p3.yzz)*p3.zyx);
}

#define AA 3

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float ar = iResolution.x / iResolution.y;
    float scale = 5.0;
    vec2 time_shift = vec2(iTime);
    time_shift.x /= ar;

    vec3 total = vec3(0.0);

    for (int aax = 0; aax < AA; aax += 1) {
    for (int aay = 0; aay < AA; aay += 1) {
        // Anit-aliasing (super-sampling)
        vec2 off = vec2(aax, aay) / float(AA);
        vec2 uv = (fragCoord + off - vec2(AA / 2)) / iResolution.xy;

        // Nearest hexagon side to the pixel
        uv.x *= ar;
        vec2 p = scale * uv + time_shift;
        vec4 hex_info = hex_side(p);
        vec2 center = hex_info.xy;
        vec2 to_side = hex_info.zw;

        // Assign a random color
        float dist = length(to_side);
        vec3 inverse_dist = vec3(1.0 - 1.5 * dist);
        vec3 hue = normalize(abs(hash32(center)));
        vec3 color = hue;

        // Add stripes
        float stripe_w = 0.05;
        color *= 0.5 * step(mod(dist, stripe_w), vec3(stripe_w / 2.0)) + 0.5;

        // Add border
        float border_w = stripe_w / 2.0;
        if (dist < border_w)
            color = vec3(0.2);

        total += color;
    }}

    vec3 col = total / float(AA * AA);

    fragColor = vec4(col, 1.0);
}
